// 路遇货物处置只消费真实战斗来源与入场快照；胜负不自行决定未作者化的损失。
#include "task_model.hpp"
#include <limits>
#include <set>
namespace hanmo::resident {
namespace {
// 历史数量和位置只使用精确整数；非法来源不能被截断成一次看似合法的转移。
bool add(Integer a,Integer b,Integer& result){if(a<0||b<0||a>std::numeric_limits<Integer>::max()-b)return false;result=a+b;return true;}
bool same_location(const Location& a,const Location& b){if(a.index()!=b.index())return false;if(auto* p=std::get_if<SettlementLocation>(&a)){const auto& q=std::get<SettlementLocation>(b);return p->place_id==q.place_id&&p->settlement_id==q.settlement_id;}if(auto* p=std::get_if<WildernessLocation>(&a)){const auto& q=std::get<WildernessLocation>(b);return p->map_id==q.map_id&&p->origin==q.origin&&p->point.x==q.point.x&&p->point.y==q.point.y;}if(auto* p=std::get_if<FollowingLocation>(&a))return p->party_id==std::get<FollowingLocation>(b).party_id;if(auto* p=std::get_if<InArmyLocation>(&a))return p->army_id==std::get<InArmyLocation>(b).army_id;const auto& p=std::get<OnRouteLocation>(a);const auto& q=std::get<OnRouteLocation>(b);return p.edge_id==q.edge_id&&p.origin==q.origin&&p.progress==q.progress;}
bool same_policy(const TaskCargoPolicy& a,const TaskCargoPolicy& b){return a.id==b.id&&a.version==b.version&&a.task_template_id==b.task_template_id&&a.item_id==b.item_id&&a.outcome==b.outcome&&a.recipient==b.recipient&&a.allocation==b.allocation&&a.unavailable_recipient==b.unavailable_recipient&&a.transfer_cap==b.transfer_cap&&a.destroy_cap==b.destroy_cap;}
// 部分交付与本次货损互不抵扣；这里只识别当前合同在实际执行者背包里的原产权。
Owner cargo_owner(const TaskCargoExposure& exposure){return {Owner::Kind::task,exposure.task_id,{}};}
Outcome<std::vector<TaskCargoLot>> manifest(const CommonStore& common,const StableId& inventory_id,const StableId& task_id,const StableId& item_id){auto* inventory=common.inventory(inventory_id);if(!inventory)return {false,{},common_failure("CargoInventoryMissing",inventory_id).error};std::vector<TaskCargoLot> lots;for(const auto& lot:inventory->lots)if(lot.owner.kind==Owner::Kind::task&&lot.owner.id==task_id&&lot.item_id==item_id){if(lot.quantity<=0||!lot.reserved_by.empty())return {false,{},common_failure("CargoReservationConflict",lot.id).error};lots.push_back({lot.id,lot.quantity});}return {true,std::move(lots),{}};}
bool same_manifest(const std::vector<TaskCargoLot>& a,const std::vector<TaskCargoLot>& b){if(a.size()!=b.size())return false;for(std::size_t i=0;i<a.size();++i)if(a[i].lot_id!=b[i].lot_id||a[i].quantity!=b[i].quantity)return false;return true;}
Status verify_source(const TaskCargoExposure& exposure,const TaskCargoBattleSource& source){if(exposure.battle_id!=source.battle_id||exposure.encounter_id!=source.encounter_id||exposure.carrier_actor_id!=source.controller_actor_id||exposure.recipient_actor_id!=source.opponent_actor_id||exposure.recipient_prototype_id!=source.opponent_prototype_id||exposure.created_tick!=source.created_tick||!same_policy(exposure.policy,source.policy)||!same_location(exposure.carrier_anchor,source.controller_anchor)||!same_location(exposure.recipient_anchor,source.opponent_anchor))return common_failure("CargoSourceMismatch",exposure.battle_id);return common_success();}
// 拒绝迟到的新货、换人换袋和远地调用；恢复后使用持久库存revision，不借进程缓存版本。
Status verify_live_custody(const CommonStore& common,const TaskCargoExposure& exposure){auto* carrier=common.actor(exposure.carrier_actor_id);auto* recipient=common.actor(exposure.recipient_actor_id);auto* source=common.inventory(exposure.source_inventory_id);auto* destination=common.inventory(exposure.destination_inventory_id);if(!carrier||!recipient||!carrier->alive||!carrier->available||!recipient->alive||!recipient->available||!source||!destination||carrier->inventory_id!=source->id||recipient->inventory_id!=destination->id||source->id==destination->id||source->owner.kind!=Owner::Kind::actor||source->owner.id!=carrier->id||destination->owner.kind!=Owner::Kind::actor||destination->owner.id!=recipient->id||source->revision!=exposure.source_inventory_revision||destination->revision!=exposure.destination_inventory_revision||destination->capacity!=exposure.destination_capacity)return common_failure("CargoCustodyChanged",exposure.battle_id);auto carrier_location=common.resolved_location(carrier->id),recipient_location=common.resolved_location(recipient->id);if(!carrier_location.ok)return {false,{},carrier_location.error};if(!recipient_location.ok)return {false,{},recipient_location.error};if(!same_location(carrier_location.value,exposure.carrier_anchor)||!same_location(recipient_location.value,exposure.recipient_anchor))return common_failure("CargoLocationChanged",exposure.battle_id);auto weight=common.inventory_weight(destination->id);if(!weight.ok)return {false,{},weight.error};if(weight.value!=exposure.destination_weight)return common_failure("CargoCustodyChanged",exposure.battle_id);if(!exposure.task_id.empty()){auto actual=manifest(common,source->id,exposure.task_id,exposure.policy.item_id);if(!actual.ok)return {false,{},actual.error};if(!same_manifest(actual.value,exposure.lots))return common_failure("CargoManifestChanged",exposure.battle_id);}return common_success();}
bool recipient_capacity(const CommonStore& common,const TaskCargoExposure& exposure){auto* item=common.item_definition(exposure.policy.item_id);if(!item||item->weight<0||exposure.destination_weight<0||exposure.destination_capacity<exposure.destination_weight)return false;return item->weight==0||exposure.transfer_quantity<=(exposure.destination_capacity-exposure.destination_weight)/item->weight;}
// 这三个跳过分支全部来自冻结内容或真实结果；没有默认失败比例或新的随机选择。
StableId skipped_reason(const CommonStore& common,const TaskCargoExposure& exposure,const TaskCargoBattleSource& source){if(exposure.frozen_quantity==0)return "no_eligible_cargo";if(source.outcome!=exposure.policy.outcome)return "outcome_not_matched";if(!source.opponent_survived||!recipient_capacity(common,exposure))return "recipient_unavailable";return {};}
}
// 处置合计只从已登记收据派生；不能把丢失量加入DeliveryFact或重复计算报酬。
Outcome<TaskCargoTotals> task_cargo_totals(const TaskState& tasks,const StableId& contract_id){const auto* contract=tasks.contracts.find(contract_id);if(!contract)return {false,{},common_failure("UnknownCargoContract",contract_id).error};TaskCargoTotals totals;std::set<StableId> seen;for(const auto& id:contract->cargo_disposition_ids){auto* fact=tasks.cargo_dispositions.find(id);auto* exposure=fact?tasks.cargo_exposures.find(fact->battle_id):nullptr;if(!fact||!exposure||exposure->resolution!=TaskCargoResolution::applied||exposure->disposition_fact_id!=id||fact->contract_id!=contract_id||!seen.insert(id).second||!add(totals.transferred_quantity,fact->transferred_quantity,totals.transferred_quantity)||!add(totals.destroyed_quantity,fact->destroyed_quantity,totals.destroyed_quantity))return {false,{},common_failure("InvalidCargoDispositionTotal",id).error};}Integer all=0;if(!add(totals.transferred_quantity,totals.destroyed_quantity,all))return {false,{},common_failure("CargoQuantityOverflow",contract_id).error};return {true,totals,{}};}
// 已实交和已认证处置不能超过冻结合同数量；未决快照绝不减少可交付份额。
Outcome<Integer> task_cargo_remaining_quantity(const TaskState& tasks,const StableId& id){auto* contract=tasks.contracts.find(id);if(!contract)return {false,{},common_failure("UnknownCargoContract",id).error};auto totals=task_cargo_totals(tasks,id);if(!totals.ok)return {false,{},totals.error};const auto agreed=contract->frozen_terms.agreed_quantity;const auto delivered=contract->delivered_quantity;const auto disposed=totals.value.transferred_quantity+totals.value.destroyed_quantity;if(agreed<=0||delivered<0||delivered>agreed||disposed>agreed-delivered)return {false,{},common_failure("CargoAccountingExceedsContract",id).error};return {true,agreed-delivered-disposed,{}};}
Status validate_task_cargo_policy(const TaskCargoPolicy& policy){Integer combined=0;if(policy.id.empty()||policy.version!="fixed_caps_v1"||policy.task_template_id.empty()||policy.item_id.empty()||policy.outcome!="defeat"||policy.recipient!="encounter_opponent"||policy.allocation!="oldest_active_contract"||policy.unavailable_recipient!="no_disposition"||!add(policy.transfer_cap,policy.destroy_cap,combined)||combined==0)return common_failure("InvalidTaskCargoPolicy",policy.id);return common_success();}
Status freeze_task_cargo_exposure(CommonStore& common,TaskState& tasks,const StableId& battle_id,const TaskCargoSourceRead& source_read){auto observed=source_read.task_cargo_source(battle_id);if(!observed.ok)return {false,{},observed.error};if(!observed.value)return tasks.cargo_exposures.find(battle_id)?common_failure("CargoPolicyMissing",battle_id):common_success();const auto& source=*observed.value;auto policy=validate_task_cargo_policy(source.policy);if(!policy.ok)return policy;if(auto* existing=tasks.cargo_exposures.find(battle_id))return verify_source(*existing,source);if(source.battle_id!=battle_id||source.phase!="planning"||source.result_applied||source.round!=1||source.created_tick!=common.tick()||!source.result_id.empty())return common_failure("CargoFreezeNotAtBattleStart",battle_id);auto* carrier=common.actor(source.controller_actor_id);auto* recipient=common.actor(source.opponent_actor_id);if(!carrier||!recipient||carrier->id==recipient->id||!carrier->alive||!recipient->alive)return common_failure("CargoParticipantMissing",battle_id);auto* bag=common.inventory(carrier->inventory_id);auto* receiver=common.inventory(recipient->inventory_id);if(!bag||!receiver)return common_failure("CargoInventoryMissing",battle_id);auto destination_weight=common.inventory_weight(receiver->id);if(!destination_weight.ok)return {false,{},destination_weight.error};TaskCargoExposure exposure;exposure.battle_id=battle_id;exposure.encounter_id=source.encounter_id;exposure.carrier_actor_id=carrier->id;exposure.recipient_actor_id=recipient->id;exposure.recipient_prototype_id=source.opponent_prototype_id;exposure.source_inventory_id=bag->id;exposure.destination_inventory_id=receiver->id;exposure.policy=source.policy;exposure.carrier_anchor=source.controller_anchor;exposure.recipient_anchor=source.opponent_anchor;exposure.created_tick=source.created_tick;exposure.source_inventory_revision=bag->revision;exposure.destination_inventory_revision=receiver->revision;exposure.destination_capacity=receiver->capacity;exposure.destination_weight=destination_weight.value;
    const TaskRecord* selected=nullptr;std::vector<TaskCargoLot> selected_lots;for(const auto& row:tasks.tasks.rows()){const auto& task=row.second;auto* contract=task.contract_id?tasks.contracts.find(*task.contract_id):nullptr;auto* offer=tasks.offer_instances.find(task.offer_id);if(task.assignee!=carrier->id||task.status!="active"||!contract||contract->status!=ContractStatus::active||contract->execution_stopped||contract->current_task_id!=std::optional<StableId>(task.id)||contract->executor_actor_id!=std::optional<StableId>(carrier->id)||!offer||offer->template_id!=source.policy.task_template_id||contract->frozen_terms.item_id!=source.policy.item_id)continue;auto lots=manifest(common,bag->id,task.id,source.policy.item_id);if(!lots.ok)return {false,{},lots.error};if(lots.value.empty())continue;if(!selected||task.serial<selected->serial){selected=&task;selected_lots=std::move(lots.value);}}if(selected){exposure.task_id=selected->id;exposure.contract_id=*selected->contract_id;exposure.lots=std::move(selected_lots);for(const auto& lot:exposure.lots)if(!add(exposure.frozen_quantity,lot.quantity,exposure.frozen_quantity))return common_failure("CargoQuantityOverflow",battle_id);exposure.transfer_quantity=std::min(exposure.frozen_quantity,source.policy.transfer_cap);exposure.destroy_quantity=std::min(exposure.frozen_quantity-exposure.transfer_quantity,source.policy.destroy_cap);auto remaining=task_cargo_remaining_quantity(tasks,exposure.contract_id);if(!remaining.ok)return {false,{},remaining.error};if(exposure.transfer_quantity>remaining.value||exposure.destroy_quantity>remaining.value-exposure.transfer_quantity)return common_failure("CargoDispositionExceedsContract",battle_id);}auto live=verify_live_custody(common,exposure);if(!live.ok)return live;tasks.cargo_exposures.insert(battle_id,std::move(exposure));return common_success();}
Status apply_task_cargo_result(CommonStore& common,TaskState& tasks,const StableId& battle_id,const TaskCargoSourceRead& source_read){auto observed=source_read.task_cargo_source(battle_id);if(!observed.ok)return {false,{},observed.error};auto* exposure=tasks.cargo_exposures.find(battle_id);if(!observed.value)return exposure?common_failure("CargoPolicyMissing",battle_id):common_success();if(!exposure)return common_failure("CargoExposureMissing",battle_id,ErrorKind::internal);const auto& source=*observed.value;auto matched=verify_source(*exposure,source);if(!matched.ok)return matched;if(!source.result_applied||(source.phase!="result"&&source.phase!="closed")||source.completed_tick<exposure->created_tick||source.completed_tick>common.tick()||source.result_id.empty())return common_failure("CargoResultNotReady",battle_id);if(exposure->resolution!=TaskCargoResolution::pending){if(exposure->source_result_id!=source.result_id||exposure->resolved_tick!=source.completed_tick)return common_failure("CargoResultReplayMismatch",battle_id);return validate_task_cargo_sources(common,tasks,source_read);}auto live=verify_live_custody(common,*exposure);if(!live.ok)return live;const auto reason=skipped_reason(common,*exposure,source);if(!reason.empty()){exposure->resolution=TaskCargoResolution::skipped;exposure->resolution_reason=reason;exposure->source_result_id=source.result_id;exposure->resolved_tick=source.completed_tick;return common_success();}auto* task=tasks.tasks.find(exposure->task_id);auto* contract=tasks.contracts.find(exposure->contract_id);if(!task||!contract||contract->status==ContractStatus::settled||task->contract_id!=std::optional<StableId>(contract->id)||contract->current_task_id!=std::optional<StableId>(task->id))return common_failure("CargoContractChanged",battle_id);auto remaining=task_cargo_remaining_quantity(tasks,contract->id);if(!remaining.ok)return {false,{},remaining.error};if(exposure->transfer_quantity>remaining.value||exposure->destroy_quantity>remaining.value-exposure->transfer_quantity)return common_failure("CargoDispositionExceedsContract",battle_id);if(common.state().next_instance_id<1||common.state().next_instance_id>=std::numeric_limits<Integer>::max()||exposure->lots.size()>static_cast<std::uint64_t>(std::numeric_limits<Integer>::max()-common.state().next_instance_id-1))return common_failure("InstanceIdOverflow");Owner recipient{Owner::Kind::actor,exposure->recipient_actor_id,{}};ResourceRecipe recipe;recipe.expected_versions={common.read_version({ResourceKey::Kind::inventory,exposure->source_inventory_id}),common.read_version({ResourceKey::Kind::inventory,exposure->destination_inventory_id})};if(exposure->transfer_quantity)recipe.operations.push_back(TransferLots{exposure->source_inventory_id,exposure->destination_inventory_id,exposure->policy.item_id,exposure->transfer_quantity,{cargo_owner(*exposure)},{},recipient});if(exposure->destroy_quantity)recipe.operations.push_back(ConsumeLots{exposure->source_inventory_id,exposure->policy.item_id,exposure->destroy_quantity,{cargo_owner(*exposure)},{}});auto changed=common.apply_resources(recipe);if(!changed.ok)return changed;auto id=common.next_id("cargo_disposition");if(!id.ok)return {false,{},id.error};TaskCargoDispositionFact fact;fact.id=id.value;fact.battle_id=battle_id;fact.encounter_id=exposure->encounter_id;fact.source_result_id=source.result_id;fact.contract_id=contract->id;fact.task_id=task->id;fact.carrier_actor_id=exposure->carrier_actor_id;fact.recipient_actor_id=exposure->recipient_actor_id;fact.from_inventory_id=exposure->source_inventory_id;fact.to_inventory_id=exposure->destination_inventory_id;fact.item_id=exposure->policy.item_id;fact.from_owner=cargo_owner(*exposure);fact.to_owner=recipient;fact.tick=source.completed_tick;fact.source_quantity_before=exposure->frozen_quantity;fact.source_quantity_after=exposure->frozen_quantity-exposure->transfer_quantity-exposure->destroy_quantity;fact.transferred_quantity=exposure->transfer_quantity;fact.destroyed_quantity=exposure->destroy_quantity;auto registered=common.append_fact({fact.id,"task_cargo_disposition","tasks"});if(!registered.ok)return registered;tasks.cargo_dispositions.insert(fact.id,fact);contract->cargo_disposition_ids.push_back(fact.id);exposure->resolution=TaskCargoResolution::applied;exposure->resolution_reason="applied";exposure->source_result_id=source.result_id;exposure->disposition_fact_id=fact.id;exposure->resolved_tick=source.completed_tick;if(contract->execution_stopped)return settle_task_contract(common,tasks,contract->id,common.tick());return common_success();}
// 本域先核对静态结构、守恒及合同反向引用；历史来源真伪由实际战斗owner继续核验。
Status validate_task_cargo_integrity(const CommonStore& common,const TaskState& tasks){std::set<StableId> receipts,results;for(const auto& row:tasks.cargo_exposures.rows()){const auto& exposure=row.second;auto policy=validate_task_cargo_policy(exposure.policy);if(!policy.ok)return policy;auto* carrier=common.actor(exposure.carrier_actor_id);auto* recipient=common.actor(exposure.recipient_actor_id);auto* source=common.inventory(exposure.source_inventory_id);auto* destination=common.inventory(exposure.destination_inventory_id);if(row.first!=exposure.battle_id||exposure.encounter_id.empty()||!carrier||!recipient||carrier==recipient||!source||!destination||carrier->inventory_id!=source->id||recipient->inventory_id!=destination->id||source->id==destination->id||exposure.recipient_prototype_id.empty()||exposure.created_tick<0||exposure.created_tick>common.tick()||exposure.source_inventory_revision<0||exposure.destination_inventory_revision<0||exposure.destination_capacity<1||exposure.destination_weight<0||exposure.destination_weight>exposure.destination_capacity||exposure.frozen_quantity<0||exposure.transfer_quantity<0||exposure.destroy_quantity<0||static_cast<Integer>(exposure.resolution)<0||static_cast<Integer>(exposure.resolution)>2)return common_failure("InvalidCargoExposure",row.first);Integer quantity=0;std::set<StableId> lot_ids;for(const auto& lot:exposure.lots)if(lot.lot_id.empty()||lot.quantity<=0||!lot_ids.insert(lot.lot_id).second||!add(quantity,lot.quantity,quantity))return common_failure("InvalidCargoManifest",row.first);if(quantity!=exposure.frozen_quantity||exposure.transfer_quantity!=std::min(quantity,exposure.policy.transfer_cap)||exposure.destroy_quantity!=std::min(quantity-exposure.transfer_quantity,exposure.policy.destroy_cap))return common_failure("CargoManifestConservation",row.first);if(quantity==0){if(!exposure.task_id.empty()||!exposure.contract_id.empty()||!exposure.lots.empty())return common_failure("UnexpectedCargoContract",row.first);}else{auto* task=tasks.tasks.find(exposure.task_id);auto* contract=tasks.contracts.find(exposure.contract_id);auto* offer=task?tasks.offer_instances.find(task->offer_id):nullptr;if(!task||!contract||!offer||task->contract_id!=std::optional<StableId>(contract->id)||task->assignee!=carrier->id||task->accepted_tick>exposure.created_tick||contract->frozen_terms.item_id!=exposure.policy.item_id||offer->template_id!=exposure.policy.task_template_id)return common_failure("CargoContractMismatch",row.first);}if(exposure.resolution==TaskCargoResolution::pending){if(exposure.resolved_tick!=-1||!exposure.source_result_id.empty()||!exposure.disposition_fact_id.empty()||!exposure.resolution_reason.empty())return common_failure("PrematureCargoResolution",row.first);auto live=verify_live_custody(common,exposure);if(!live.ok)return live;continue;}auto* original=common.state().facts.find(exposure.battle_id);if(!original||original->kind!="personal_battle"||original->domain!="personal"||exposure.source_result_id.empty()||exposure.resolved_tick<exposure.created_tick||exposure.resolved_tick>common.tick()||!results.insert(exposure.source_result_id).second)return common_failure("InvalidCargoResultSource",row.first);if(exposure.resolution==TaskCargoResolution::skipped){if(!exposure.disposition_fact_id.empty()||(exposure.resolution_reason!="no_eligible_cargo"&&exposure.resolution_reason!="outcome_not_matched"&&exposure.resolution_reason!="recipient_unavailable")||(exposure.resolution_reason=="no_eligible_cargo"&&quantity!=0))return common_failure("InvalidSkippedCargoResult",row.first);continue;}auto* receipt=tasks.cargo_dispositions.find(exposure.disposition_fact_id);if(!receipt||exposure.resolution_reason!="applied"||quantity<=0||!receipts.insert(receipt->id).second)return common_failure("MissingCargoDisposition",row.first);const auto* header=common.state().facts.find(receipt->id);if(receipt->id!=exposure.disposition_fact_id||!header||header->kind!="task_cargo_disposition"||header->domain!="tasks"||receipt->battle_id!=exposure.battle_id||receipt->encounter_id!=exposure.encounter_id||receipt->source_result_id!=exposure.source_result_id||receipt->contract_id!=exposure.contract_id||receipt->task_id!=exposure.task_id||receipt->carrier_actor_id!=exposure.carrier_actor_id||receipt->recipient_actor_id!=exposure.recipient_actor_id||receipt->from_inventory_id!=source->id||receipt->to_inventory_id!=destination->id||receipt->item_id!=exposure.policy.item_id||!owner_equal(receipt->from_owner,cargo_owner(exposure))||receipt->to_owner.kind!=Owner::Kind::actor||receipt->to_owner.id!=recipient->id||receipt->tick!=exposure.resolved_tick||receipt->source_quantity_before!=quantity||receipt->transferred_quantity!=exposure.transfer_quantity||receipt->destroyed_quantity!=exposure.destroy_quantity||receipt->source_quantity_after!=quantity-exposure.transfer_quantity-exposure.destroy_quantity)return common_failure("CargoDispositionMismatch",row.first);}
    if(receipts.size()!=tasks.cargo_dispositions.size())return common_failure("UnboundCargoDisposition");std::set<StableId> linked;for(const auto& row:tasks.contracts.rows())for(const auto& id:row.second.cargo_disposition_ids){auto* fact=tasks.cargo_dispositions.find(id);if(!fact||fact->contract_id!=row.first||!linked.insert(id).second)return common_failure("CargoContractReceiptMismatch",id);}if(linked.size()!=tasks.cargo_dispositions.size())return common_failure("UnlinkedCargoDisposition");for(const auto& row:tasks.contracts.rows()){auto remaining=task_cargo_remaining_quantity(tasks,row.first);if(!remaining.ok)return {false,{},remaining.error};if(row.second.stop_reason=="cargo_loss"&&(remaining.value!=0||row.second.cargo_disposition_ids.empty()))return common_failure("InvalidCargoLossClosure",row.first);}return common_success();}
// 恢复必须查询实际战斗和作者来源；已处置货物后续交易不要求旧库存revision继续不变。
Status validate_task_cargo_sources(const CommonStore& common,const TaskState& tasks,const TaskCargoSourceRead& source_read){auto local=validate_task_cargo_integrity(common,tasks);if(!local.ok)return local;std::set<StableId> expected;for(const auto& id:source_read.task_cargo_sources()){if(!expected.insert(id).second)return common_failure("DuplicateCargoSource",id);auto source=source_read.task_cargo_source(id);if(!source.ok)return {false,{},source.error};if(!source.value||!tasks.cargo_exposures.find(id))return common_failure("MissingCargoExposure",id);}if(expected.size()!=tasks.cargo_exposures.size())return common_failure("UnexpectedCargoExposure");for(const auto& row:tasks.cargo_exposures.rows()){const auto& exposure=row.second;auto observed=source_read.task_cargo_source(row.first);if(!observed.ok)return {false,{},observed.error};if(!observed.value)return common_failure("CargoPolicyMissing",row.first);const auto& source=*observed.value;auto matched=verify_source(exposure,source);if(!matched.ok)return matched;if(exposure.resolution==TaskCargoResolution::pending){if(source.phase!="planning"||source.result_applied||!source.result_id.empty())return common_failure("UnresolvedCargoResult",row.first);continue;}if(!source.result_applied||(source.phase!="result"&&source.phase!="closed")||source.result_id!=exposure.source_result_id||source.completed_tick!=exposure.resolved_tick)return common_failure("CargoResultSourceMismatch",row.first);const auto skipped=skipped_reason(common,exposure,source);if(exposure.resolution==TaskCargoResolution::skipped){if(skipped.empty()||exposure.resolution_reason!=skipped)return common_failure("CargoSkipSourceMismatch",row.first);}else if(!skipped.empty())return common_failure("CargoDispositionUnauthorized",row.first);}return common_success();}
} // 原始合同份额和交付奖励不随货损递减；真实剩余货物与来源收据共同决定后续清算。
